Actionscript.script:
stop();
function duperoid()
{
    ++_root.i;
    spot = random(3);
    if (spot == 0)
    {
        _root.dX = 0;
        _root.dY = 0;
    } // end if
    if (spot == 1)
    {
        _root.dX = 550;
        _root.dY = 0;
    } // end if
    if (spot == 2)
    {
        _root.dX = 0;
        _root.dY = 400;
    } // end if
    if (spot == 3)
    {
        _root.dX = 550;
        _root.dY = 400;
    } // end if
    duplicateMovieClip(_root.roid, "roi" + _root.i, _root.i);
    with (_root["roi" + _root.i])
    {
        _x = _root.dX;
        _y = _root.dY;
    } // End of with
} // End of the function
function duperoidB()
{
    ++_root.i;
    duplicateMovieClip(_root.roidB, "roiB" + _root.i, _root.i);
    with (_root["roiB" + _root.i])
    {
        _x = _root.dX;
        _y = _root.dY;
    } // End of with
} // End of the function
function duperoidC()
{
    ++_root.i;
    duplicateMovieClip(_root.roidC, "roiC" + _root.i, _root.i);
    with (_root["roiC" + _root.i])
    {
        _x = _root.dX;
        _y = _root.dY;
    } // End of with
} // End of the function
var myMenu = new ContextMenu();
myMenu.hideBuiltInItems();
item1 = new ContextMenuItem("CG3Studios", itemHandler1);
myMenu.customItems.push(item1);
_root.menu = myMenu;
var lives = 1;
var score = 0;
var i = 1000;
var dX = 0;
var dY = 0;
var spot = 0;
var bc = 500;
var fi = 0;
var hi = 0;
var level = 1;
var acc = 0;
var diff = 0;
var kills = 0;
var ttle = 0;
lives_hold.text = "Lives: " + lives;
score_hold.text = "Score: " + score;
level_hold.text = "Level: " + level;
acc_hold.text = "Accuracy" + acc + "%";
_root.onEnterFrame = function ()
{
    Mouse.hide();
    lives_hold.text = "Lives: " + lives;
    score_hold.text = "Score: " + score;
    level_hold.text = "Level: " + level;
    acc = Math.round(hi / fi * 100);
    if (fi == 0)
    {
        acc_hold.text = "Accuracy: 0%";
    }
    else
    {
        acc_hold.text = "Accuracy: " + acc + "%";
    } // end else if
    if (i > 1100)
    {
        i = 100;
    } // end if
    if (bc > 600)
    {
        bc = 500;
    } // end if
    if (lives < 0)
    {
        _root.gotoAndStop("lose");
    } // end if
};

diff = 0;
lives = 5;
ttle = 14;
kills = 0;
for (z = 0; z < 2; z++)
{
    duperoid();
} // end of for

onClipEvent (load) {
	if(_root.lenguage=="russia")
	gotoAndStop("rus");
	else if(_root.lenguage=="english")
	gotoAndStop("eng");
}

onClipEvent (load) {
	if(_root.lenguage=="russia")
	gotoAndStop("rus");
	else if(_root.lenguage=="english")
	gotoAndStop("eng");
}

onClipEvent (load) {
	if(_root.lenguage=="russia")
	gotoAndStop("rus");
	else if(_root.lenguage=="english")
	gotoAndStop("eng");
}

onClipEvent (load)
{
    if (_root.diff == 0)
    {
        var speed = 7;
    } // end if
    if (_root.diff == 1)
    {
        var speed = 7.500000;
    } // end if
    if (_root.diff == 2)
    {
        var speed = 8;
    } // end if
    var dead = false;
    setProperty("", _rotation, random(360));
    if (_name == "roidB")
    {
        setProperty("", _x, 1000);
        setProperty("", _y, 1000);
    } // end if
}
onClipEvent (enterFrame)
{
    if (_name != "roidB")
    {
        setProperty("", _rotation, ++_rotation);
        for (i in _root)
        {
            if (_root[i]._name.indexOf("las") != -1)
            {
                if (_root[i].hitTest(this) && dead == false)
                {
                    ++_root.hi;
                    _root[i].removeMovieClip();
                    _root.dX = _x;
                    _root.dY = _y;
                    _root.duperoidC();
                    _root.duperoidC();
                    this.gotoAndStop(2);
                    if (_root.diff == 0)
                    {
                        _root.score = _root.score + 10;
                    } // end if
                    if (_root.diff == 1)
                    {
                        _root.score = _root.score + 15;
                    } // end if
                    if (_root.diff == 2)
                    {
                        _root.score = _root.score + 20;
                    } // end if
                    dead = true;
                } // end if
            } // end if
        } // end of for...in
        if (_root.ship.body.hitTest(this) && _root.ship._currentframe == 1 && _root.ship.invs == 0 && dead == false)
        {
            _root.ship.play();
            _root.dX = _x;
            _root.dY = _y;
            _root.duperoidC();
            _root.duperoidC();
            this.gotoAndStop(2);
            dead = true;
        } // end if
        YY = speed * Math.cos(0.017453 * _rotation);
        XX = speed * Math.sin(0.017453 * _rotation);
        if (_rotation > 180)
        {
            setProperty("", _y, _y + YY);
            setProperty("", _x, _x - XX);
        }
        else
        {
            setProperty("", _y, _y - YY);
            setProperty("", _x, _x + XX);
        } // end else if
        if (_x > 550)
        {
            setProperty("", _x, 0);
        } // end if
        if (_x < 0)
        {
            setProperty("", _x, 550);
        } // end if
        if (_y > 400)
        {
            setProperty("", _y, 0);
        } // end if
        if (_y < 0)
        {
            setProperty("", _y, 400);
        } // end if
        if (_root.lives < 0)
        {
            this.removeMovieClip();
        } // end if
        if (this.death._currentframe == 7)
        {
            this.removeMovieClip();
        } // end if
    } // end if
}

