onClipEvent (load)
{
    this.cacheAsBitmap = true;
    var spd = 20;
    var time = 25;
    setProperty("", _x, _root.ship._x);
    setProperty("", _y, _root.ship._y);
    setProperty("", _rotation, _root.ship._rotation);
    if (_name == "laser")
    {
        setProperty("", _x, 1000);
        setProperty("", _y, 1000);
    } // end if
}
onClipEvent (enterFrame)
{
    if (_name != "laser")
    {
        --time;
        if (_rotation > 180)
        {
            setProperty("", _y, _y + spd * Math.cos(0.017453 * _rotation));
            setProperty("", _x, _x - spd * Math.sin(0.017453 * _rotation));
        }
        else
        {
            setProperty("", _y, _y - spd * Math.cos(0.017453 * _rotation));
            setProperty("", _x, _x + spd * Math.sin(0.017453 * _rotation));
        } // end else if
        if (_x > 550 || _x < 0 || _y > 400 || _y < 0 || _root.lives < 0)
        {
            this.removeMovieClip();
        } // end if
    } // end if
}

onClipEvent (load)
{
    thrust = 0.500000;
    decay = 0.980000;
    maxSpeed = 10;
    ySpeed = 0;
    xSpeed = 0;
    invs = 15;
    rot = 10;
    shooting = false;
    this.fire._visible = false;
    swapDepths(9999);
    setProperty("", _x, 275);
    setProperty("", _y, 200);
}
onClipEvent (enterFrame)
{
    if (invs > 0)
    {
        --invs;
        this.shield._visible = true;
    }
    else
    {
        this.shield._visible = false;
    } // end else if
    if (_currentframe == 1 || _currentframe == 34)
    {
        setProperty("", _y, _y - ySpeed);
        setProperty("", _x, _x + xSpeed);
        if (Key.isDown(32) && shooting == false)
        {
            ++_root.bc;
            duplicateMovieClip(_root.laser, "las" + _root.bc, _root.bc);
            ++_root.fi;
            shooting = true;
        } // end if
        !Key.isDown(32) ? (shooting = false) : (null);
        if (Key.isDown(16) && warp == false)
        {
            setProperty("", _x, random(550));
            setProperty("", _y, random(400));
            warp = true;
        } // end if
        !Key.isDown(16) ? (warp = false) : (null);
        if (Key.isDown(39))
        {
            setProperty("", _rotation, _rotation + rot);
        } // end if
        if (Key.isDown(37))
        {
            setProperty("", _rotation, _rotation - rot);
        } // end if
        if (Key.isDown(38))
        {
            xSpeed = xSpeed + thrust * Math.sin(_rotation * 0.017453);
            ySpeed = ySpeed + thrust * Math.cos(_rotation * 0.017453);
            this.fire._visible = true;
        }
        else
        {
            this.fire._visible = false;
            xSpeed = xSpeed * decay;
            ySpeed = ySpeed * decay;
        } // end else if
        speed = Math.sqrt(xSpeed * xSpeed + ySpeed * ySpeed);
        if (speed > maxSpeed)
        {
            xSpeed = xSpeed * (maxSpeed / speed);
            ySpeed = ySpeed * (maxSpeed / speed);
        } // end if
        if (_y < 0)
        {
            setProperty("", _y, 399);
        } // end if
        if (_y > 399)
        {
            setProperty("", _y, 0);
        } // end if
        if (_x < 0)
        {
            setProperty("", _x, 549);
        } // end if
        if (_x > 549)
        {
            setProperty("", _x, 0);
        } // end if
    }
    else
    {
        this.fire._visible = false;
        ySpeed = 0;
        xSpeed = 0;
    } // end else if
    if (_root.lives < 0)
    {
        this.removeMovieClip();
    } // end if
}
